+// API keys, roles and the audit log. Keys live in `apiKeys`
+// ([{ key, name, role }]); every request that changes data adds an entry to
+// `audit` ({ id, at, keyName, method, path, status }). Entries are never
+// edited or deleted.
+import { createHash, timingSafeEqual } from "node:crypto";
+
+/** What each role may do: "read" (GET), "cook" (kitchen work), "manage" (everything else). */
+export const ROLES = Object.freeze({
+  viewer: Object.freeze(["read"]),
+  cook: Object.freeze(["read", "cook"]),
+  manager: Object.freeze(["read", "cook", "manage"]),
+});
+
+const digest = (s) => createHash("sha256").update(String(s)).digest();
+
+/** The API key record for a presented key, or null if it is unknown. */
+export function findKey(store, presented) {
+  if (typeof presented !== "string" || presented === "") return null;
+  const want = digest(presented);
+  let found = null;
+  for (const k of store.data.apiKeys ?? []) {
+    if (typeof k.key === "string" && k.key !== "" && timingSafeEqual(digest(k.key), want) && !found) found = k;
+  }
+  return found;
+}
+
+/** Whether `role` may perform `action` ("read", "cook" or "manage"). */
+export function allows(role, action) {
+  return Object.hasOwn(ROLES, role) && ROLES[role].includes(action);
+}
+
+/** Appends an audit entry; returns it. */
+export function recordAudit(store, { keyName, method, path, status }, { at }) {
+  store.data.audit ??= [];
+  const entry = { id: store.nextId("audit"), at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].sort((a, b) => b.id - a.id);
+}
