new file mode 100644
index 0000000..8ed596a
--- /dev/null
+++ b/tests/access.test.js
@@ -0,0 +1,55 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { KEYS, app, auth } from "./helpers.js";
+
+test("requests without a key or with an unknown key are 401", async () => {
+  const { raw } = app();
+  const none = await raw({ path: "/items" });
+  assert.equal(none.status, 401);
+  assert.equal(none.body.error.code, "unauthorized");
+  const unknown = await raw({ path: "/items", headers: auth("nope") });
+  assert.equal(unknown.status, 401);
+  assert.equal(unknown.body.error.code, "unauthorized");
+  const notBearer = await raw({ path: "/items", headers: { authorization: KEYS.manager } });
+  assert.equal(notBearer.status, 401);
+});
+
+test("viewers may only read", async () => {
+  const { handle, store } = app(undefined, KEYS.viewer);
+  assert.equal((await handle({ path: "/items" })).status, 200);
+  const before = JSON.stringify(store.data.batches);
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  assert.equal(res.status, 403);
+  assert.equal(res.body.error.code, "forbidden");
+  assert.equal(JSON.stringify(store.data.batches), before);
+  assert.equal((await handle({ path: "/audit" })).status, 403);
+});
+
+test("cooks may cook, waste, log temperatures and count, but not more", async () => {
+  const { store } = app();
+  const take = (await app(store).handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  const { handle } = app(store, KEYS.cook);
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", body: { qty: 0.5 } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", body: { location: "fridge", celsius: 3 } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: 6, counted: 12 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish` })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", body: { location: "fridge" } })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/orders/1/cancel" })).status, 403);
+  assert.equal((await handle({ path: "/audit" })).status, 403);
+});
+
+test("changes are audited, newest first, for managers", async () => {
+  const { store } = app();
+  await app(store, KEYS.cook).handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  await app(store, KEYS.viewer).handle({ method: "POST", path: "/jobs/nightly" });
+  await app(store).handle({ path: "/items" });
+  const res = await app(store).handle({ path: "/audit" });
+  assert.equal(res.status, 200);
+  assert.deepEqual(res.body.map(({ keyName, method, path, status }) => ({ keyName, method, path, status })), [
+    { keyName: "Front of house", method: "POST", path: "/jobs/nightly", status: 403 },
+    { keyName: "Line cook", method: "POST", path: "/recipes/1/cook", status: 200 },
+  ]);
+  assert.equal(res.body[0].at, "2026-10-28T10:00:00.000Z");
+  assert.ok(!JSON.stringify(res.body).includes("dev-key"));
+});
